// Command genericsgen writes the hash sweeps of generic code (Phase 07, step 7.12;
// tests/run/generics_sweep_*.gp are generated by it). Each program is valid Go: it runs a matrix of
// operations over many types through GENERIC functions (type parameters with type sets) and prints
// one 64-bit hash per type and family, so that real Go and gocpp must agree on every result of
// every operation: wrap-around of the small integers, division and remainder (including the panic
// for a zero divisor and MinInt / -1), shifts by counts of every integer type, conversions between
// all numeric types, floating point with NaN, -0 and infinities, strings and byte slices through
// ~string | ~[]byte, complex numbers, and ordering (min, max, cmp.Compare, slices.Sort).
//
//	go run ./tools/genericsgen -family ints -seed 1 -count 1     # prints the program
//	go run ./tools/genericsgen -tests tests/run -seed 1 -count 2 # writes tests/run/generics_sweep_<family>_NN.gp
//	                                                             # with the // Output: block that real Go prints
//
// The values are fixed boundary values plus values drawn from the seed, so a new seed gives a
// new test of the same shape. The expected output comes from real Go (`go run` of the program
// itself, which is why the .gp file is valid Go); a mismatch in a hash means that some operation
// of some type differs, and the generator's -debug flag prints the programs with a line for
// every operation instead of the hash, to find which.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"math/rand"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

var families = []string{"ints", "conv", "floats", "strings", "complex", "order"}

func main() {
	family := flag.String("family", "", "one of "+strings.Join(families, ", ")+" (default: all, with -tests)")
	seed := flag.Int64("seed", 1, "the seed of the first program")
	count := flag.Int("count", 1, "the number of programs of each family")
	tests := flag.String("tests", "", "write generics_sweep_<family>_NN.gp tests (with the output of real Go) into this folder")
	debug := flag.Bool("debug", false, "print a line for every operation instead of one hash for each type")
	flag.Parse()
	fams := families
	if *family != "" {
		fams = []string{*family}
	}
	for _, fam := range fams {
		for i := range *count {
			s := *seed + int64(i)
			rng := rand.New(rand.NewSource(s*1000 + int64(len(fam))))
			src := program(fam, rng, *debug)
			if *tests == "" {
				fmt.Print(src)
				continue
			}
			phase := "09" // math, strings and slices
			text := "// phase: " + phase + "\n\n" + src + "\n// Output:\n" + commentLines(runGo(src))
			name := fmt.Sprintf("generics_sweep_%s_%02d.gp", fam, i+1)
			must(os.WriteFile(filepath.Join(*tests, name), []byte(text), 0o644))
		}
	}
}

func must(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

// runGo runs the program with real Go and returns its output.
func runGo(src string) string {
	dir, err := os.MkdirTemp("", "genericsgen")
	must(err)
	defer os.RemoveAll(dir)
	must(os.WriteFile(filepath.Join(dir, "go.mod"), []byte("module m\n\ngo 1.25\n"), 0o644))
	must(os.WriteFile(filepath.Join(dir, "main.go"), []byte(src), 0o644))
	build := exec.Command("go", "build", "-o", "prog", ".")
	build.Dir = dir
	build.Env = append(os.Environ(), "GOTOOLCHAIN=local", "GOWORK=off", "GOFLAGS=", "GOAMD64=v1")
	if out, err := build.CombinedOutput(); err != nil {
		fmt.Fprintf(os.Stderr, "go build: %v\n%s\n", err, out)
		os.Exit(1)
	}
	cmd := exec.Command(filepath.Join(dir, "prog"))
	cmd.Dir = dir
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		fmt.Fprintf(os.Stderr, "run: %v\n%s\n", err, stderr.String())
		os.Exit(1)
	}
	return stdout.String()
}

// commentLines returns the output as the lines of a // Output: block.
func commentLines(out string) string {
	var b strings.Builder
	for _, l := range strings.Split(strings.TrimRight(out, "\n"), "\n") {
		if l == "" {
			b.WriteString("//\n")
		} else {
			b.WriteString("// " + strings.TrimRight(l, " ") + "\n")
		}
	}
	return b.String()
}

// The common part of every program: the hasher and the small helpers.
const prelude = `package main

import (
	"cmp"
	"fmt"
	"math"
	"slices"
)

type hasher struct {
	h     uint64
	debug bool
	name  string
	n     int
}

func newHasher(name string) *hasher { return &hasher{h: 14695981039346656037, name: name} }

func (x *hasher) u64(v uint64) {
	if x.debug {
		x.n++
		fmt.Println(x.name, x.n, v)
	}
	for i := 0; i < 8; i++ {
		x.h ^= (v >> (8 * i)) & 0xff
		x.h *= 1099511628211
	}
}
func (x *hasher) bool(b bool) {
	if b {
		x.u64(1)
	} else {
		x.u64(0)
	}
}
func (x *hasher) f64(f float64) {
	if f != f {
		x.u64(0x7ff8000000000001) // every NaN is one value
		return
	}
	x.u64(math.Float64bits(f))
}
func (x *hasher) f32(f float32) {
	if f != f {
		x.u64(0x7fc00001)
		return
	}
	x.u64(uint64(math.Float32bits(f)))
}
func (x *hasher) str(s string) {
	x.u64(uint64(len(s)))
	for i := 0; i < len(s); i++ {
		x.h ^= uint64(s[i])
		x.h *= 1099511628211
	}
}
func (x *hasher) done() {
	if x.debug {
		return
	}
	fmt.Printf("%-10s %016x\n", x.name, x.h)
}

func recoverText(f func()) (msg string) {
	defer func() {
		if r := recover(); r != nil {
			msg = fmt.Sprint(r)
		}
	}()
	f()
	return ""
}

var _ = math.Pi
var _ = cmp.Compare[int]
var _ = slices.Max[[]int]
`

func program(fam string, rng *rand.Rand, debug bool) string {
	var b strings.Builder
	b.WriteString("// Generated by tools/genericsgen (family " + fam + "): a hash sweep of generic code, compared with real Go.\n")
	b.WriteString(prelude)
	switch fam {
	case "ints":
		intsProgram(&b, rng)
	case "conv":
		convProgram(&b, rng)
	case "floats":
		floatsProgram(&b, rng)
	case "strings":
		stringsProgram(&b, rng)
	case "complex":
		complexProgram(&b, rng)
	case "order":
		orderProgram(&b, rng)
	default:
		must(fmt.Errorf("unknown family %q", fam))
	}
	out := b.String()
	if debug {
		out = strings.Replace(out, "newHasher(name string) *hasher { return &hasher{h: 14695981039346656037, name: name} }", "newHasher(name string) *hasher { return &hasher{h: 14695981039346656037, name: name, debug: true} }", 1)
	}
	return out
}

// intValues returns the raw values (int64 bit patterns) that the integer sweeps convert to each type:
// the boundaries of every width and some random values.
func intValues(rng *rand.Rand, random int) []int64 {
	v := []int64{0, 1, 2, 3, 7, 8, 63, 64, 100, 126, 127, 128, 129, 200, 254, 255, 256, 257,
		32766, 32767, 32768, 32769, 65534, 65535, 65536, 65537,
		1<<31 - 1, 1 << 31, 1<<31 + 1, 1<<32 - 1, 1 << 32, 1<<32 + 1,
		1<<63 - 1, -1 << 63, -1, -2, -3, -127, -128, -129, -255, -256, -32768, -32769, -65536, -1 << 31, -1<<31 - 1, -1 << 32}
	for range random {
		x := rng.Int63()
		switch rng.Intn(4) {
		case 0:
			x &= 0xff
		case 1:
			x &= 0xffff
		case 2:
			x &= 0xffffffff
		}
		if rng.Intn(2) == 0 {
			x = -x
		}
		v = append(v, x)
	}
	return v
}

func rawList(v []int64) string {
	var parts []string
	for _, x := range v {
		parts = append(parts, fmt.Sprint(x))
	}
	return strings.Join(parts, ", ")
}

// intTypes are the integer types of the sweeps: the predeclared ones and defined types over some.
var intTypes = []string{"int8", "int16", "int32", "int64", "int", "uint8", "uint16", "uint32", "uint64", "uint", "uintptr", "MyI8", "MyU16", "MyI64", "MyU32"}

const intDefs = `
type Int interface {
	~int8 | ~int16 | ~int32 | ~int64 | ~int | ~uint8 | ~uint16 | ~uint32 | ~uint64 | ~uint | ~uintptr
}

type Float interface{ ~float32 | ~float64 }

type Number interface{ Int | Float }

type MyI8 int8
type MyU16 uint16
type MyI64 int64
type MyU32 uint32
`

func intsProgram(b *strings.Builder, rng *rand.Rand) {
	raw := intValues(rng, 14)
	b.WriteString(intDefs)
	fmt.Fprintf(b, "\nvar raw = []int64{%s}\n", rawList(raw))
	b.WriteString(`
func values[T Int]() []T {
	out := make([]T, len(raw))
	for i, r := range raw {
		out[i] = T(r)
	}
	return out
}

func divmod[T Int](a, b T) (q, r T, panicked bool) {
	defer func() {
		if recover() != nil {
			panicked = true
		}
	}()
	return a / b, a % b, false
}

func shl[T Int, S Int](a T, s S) (res T, panicked bool) {
	defer func() {
		if recover() != nil {
			panicked = true
		}
	}()
	return a << s, false
}

func shr[T Int, S Int](a T, s S) (res T, panicked bool) {
	defer func() {
		if recover() != nil {
			panicked = true
		}
	}()
	return a >> s, false
}

func shifts[T Int, S Int](h *hasher, a T, counts []int) {
	for _, c := range counts {
		s := S(c)
		if int64(s) != int64(c) {
			continue // does not fit the type of the count
		}
		l, p1 := shl(a, s)
		r, p2 := shr(a, s)
		h.u64(uint64(l))
		h.u64(uint64(r))
		h.bool(p1)
		h.bool(p2)
	}
}

var counts = []int{0, 1, 2, 3, 5, 7, 8, 9, 15, 16, 17, 31, 32, 33, 63, 64, 65, 100, 127, 200, 255, 300, 1000}
var negCounts = []int{-1, -2, -100}

func sweep[T Int](name string) {
	h := newHasher(name)
	vs := values[T]()
	for _, a := range vs {
		h.u64(uint64(-a))
		h.u64(uint64(^a))
		h.u64(uint64(+a))
		b := a
		b++
		h.u64(uint64(b))
		b = a
		b--
		h.u64(uint64(b))
		b = a
		b += a
		b *= a
		b -= a
		b ^= a
		b |= 3
		b &^= 5
		b <<= 2
		b >>= 1
		h.u64(uint64(b))
		shifts[T, uint8](h, a, counts)
		shifts[T, uint16](h, a, counts)
		shifts[T, uint32](h, a, counts)
		shifts[T, uint64](h, a, counts)
		shifts[T, uint](h, a, counts)
		shifts[T, int](h, a, append(append([]int{}, counts...), negCounts...))
		shifts[T, int8](h, a, append(append([]int{}, counts[:16]...), negCounts...))
		shifts[T, int64](h, a, append(append([]int{}, counts...), negCounts...))
		for _, c := range vs {
			h.u64(uint64(a + c))
			h.u64(uint64(a - c))
			h.u64(uint64(a * c))
			h.u64(uint64(a & c))
			h.u64(uint64(a | c))
			h.u64(uint64(a ^ c))
			h.u64(uint64(a &^ c))
			q, r, p := divmod(a, c)
			h.u64(uint64(q))
			h.u64(uint64(r))
			h.bool(p)
			h.bool(a < c)
			h.bool(a <= c)
			h.bool(a == c)
			h.bool(a != c)
			h.bool(a > c)
			h.bool(a >= c)
			h.u64(uint64(max(a, c)))
			h.u64(uint64(min(a, c)))
		}
	}
	h.done()
}

func main() {
`)
	for _, t := range intTypes {
		fmt.Fprintf(b, "\tsweep[%s](%q)\n", t, t)
	}
	b.WriteString("}\n")
}

