// floatValues are the float64 values of the float sweeps.
func floatValues(rng *rand.Rand, random int) []string {
	v := []string{"0", "math.Copysign(0, -1)", "1", "-1", "0.1", "-0.1", "0.5", "1.5", "2.5", "3", "10", "100", "1e10", "-1e10",
		"1e38", "3.4e38", "1e39", "1e300", "1.7976931348623157e308", "-1.7976931348623157e308",
		"1e-5", "1e-38", "1e-45", "1e-46", "1e-300", "5e-324", "2.2250738585072014e-308",
		"16777216", "16777217", "9007199254740992", "9007199254740993", "math.Inf(1)", "math.Inf(-1)", "math.NaN()", "math.Pi", "math.E", "0.3", "0.7"}
	for range random {
		m := rng.Float64()*2 - 1
		e := rng.Intn(80) - 40
		v = append(v, fmt.Sprintf("%v", m*pow10(e)))
	}
	return v
}

func pow10(e int) float64 {
	r := 1.0
	for ; e > 0; e-- {
		r *= 10
	}
	for ; e < 0; e++ {
		r /= 10
	}
	return r
}

func floatsProgram(b *strings.Builder, rng *rand.Rand) {
	vals := floatValues(rng, 12)
	b.WriteString(intDefs)
	fmt.Fprintf(b, "\nvar raw = []float64{%s}\n", strings.Join(vals, ", "))
	b.WriteString(`
type MyF32 float32
type MyF64 float64

func values[F Float]() []F {
	out := make([]F, len(raw))
	for i, r := range raw {
		out[i] = F(r)
	}
	return out
}

func bits[F Float](h *hasher, is32 bool, f F) {
	if is32 {
		h.f32(float32(f))
	} else {
		h.f64(float64(f))
	}
}

func sweep[F Float](name string, is32 bool) {
	h := newHasher(name)
	vs := values[F]()
	for _, a := range vs {
		bits(h, is32, -a)
		bits(h, is32, +a)
		bits(h, is32, a*a)
		bits(h, is32, a/3)
		bits(h, is32, a+1)
		bits(h, is32, a-1)
		bits(h, is32, F(float32(a)))
		bits(h, is32, F(float64(a)))
		bits(h, is32, a*0.1+0.7)
		x := a
		x += a
		x *= 0.3
		x -= 7
		x /= 1.5
		bits(h, is32, x)
		bits(h, is32, F(1)/a)
		for _, c := range vs {
			bits(h, is32, a+c)
			bits(h, is32, a-c)
			bits(h, is32, a*c)
			bits(h, is32, a/c)
			h.bool(a < c)
			h.bool(a <= c)
			h.bool(a == c)
			h.bool(a != c)
			h.bool(a > c)
			h.bool(a >= c)
			bits(h, is32, max(a, c))
			bits(h, is32, min(a, c))
			bits(h, is32, a*c+a)
			bits(h, is32, (a+c)*(a-c))
		}
		h.str(fmt.Sprint(a))
		h.str(fmt.Sprintf("%v %g %e %.3f %8.2f %+g", a, a, a, a, a, a))
	}
	h.done()
}

func main() {
	sweep[float32]("float32", true)
	sweep[float64]("float64", false)
	sweep[MyF32]("MyF32", true)
	sweep[MyF64]("MyF64", false)
}
`)
}

func stringsProgram(b *strings.Builder, rng *rand.Rand) {
	parts := []string{`""`, `"a"`, `"abc"`, `"hello, world"`, `"日本語"`, `"héllo"`, `"\xff\xfe"`, `"a\x00b"`, `"é́"`, `"😀x😀"`, `"Z"`, `"z"`, `"ab"`, `"abd"`, `"\xed\xa0\x80"`, `"\xc0\x80"`, `"tab\there"`}
	letters := "abcdefghij日本é"
	for range 8 {
		var sb strings.Builder
		for range rng.Intn(9) {
			rs := []rune(letters)
			sb.WriteRune(rs[rng.Intn(len(rs))])
		}
		parts = append(parts, fmt.Sprintf("%q", sb.String()))
	}
	fmt.Fprintf(b, "\nvar raw = []string{%s}\n", strings.Join(parts, ", "))
	b.WriteString(`
type Text string
type Raw []byte
type Name string

type Bytes interface{ ~string | ~[]byte }

func lenIndex[T Bytes](h *hasher, t T) {
	h.u64(uint64(len(t)))
	for i := 0; i < len(t); i++ {
		h.u64(uint64(t[i]))
	}
	for i, c := range string(t) {
		h.u64(uint64(i))
		h.u64(uint64(c))
	}
	h.str(string(t))
	for _, r := range []rune(string(t)) {
		h.u64(uint64(r))
	}
	if len(t) >= 2 {
		h.str(string(t[1:]))
		h.str(string(t[:len(t)-1]))
		h.str(string(t[len(t)/2 : len(t)/2+1]))
	}
	h.str(string([]byte(string(t))))
	h.u64(uint64(len(append([]byte(nil), t...))))
}

func concat[S ~string](h *hasher, vs []S) {
	for _, a := range vs {
		for _, c := range vs {
			s := a + c
			h.str(string(s))
			h.bool(a < c)
			h.bool(a <= c)
			h.bool(a == c)
			h.bool(a > c)
			h.bool(a >= c)
			h.bool(a != c)
			h.str(string(max(a, c)))
			h.str(string(min(a, c)))
		}
		s := a
		s += "!"
		s += a
		h.str(string(s))
		h.str(string(S(rune(len(a)) + 'a')))
		h.u64(uint64(len(a + a + a)))
	}
}

func conv[S ~string, B ~[]byte](h *hasher, vs []S) {
	for _, a := range vs {
		b := B(a)
		h.u64(uint64(len(b)))
		h.str(string(b))
		if len(b) > 0 {
			b[0] ^= 0x20
		}
		h.str(string(b))
		h.str(string(a)) // the string is unchanged by the change of the copy
		h.str(string(S(b)))
		rs := []rune(a)
		h.u64(uint64(len(rs)))
		for _, r := range rs {
			h.u64(uint64(r))
		}
		h.str(string(S(rs)))
	}
}

func runes[I ~int8 | ~int32 | ~uint8 | ~uint32 | ~int | ~uint64, S ~string](h *hasher) {
	for _, r := range []int64{0, 65, 127, 128, 255, 256, 0x7ff, 0x800, 0xd7ff, 0xd800, 0xdfff, 0xe000, 0xffff, 0x10000, 0x10ffff, 0x110000, -1, 1 << 40} {
		i := I(r)
		h.str(string(S(i)))
		h.str(string(rune(i)))
	}
}

func sweep(name string) {
	h := newHasher(name)
	switch name {
	case "string":
		for _, s := range raw {
			lenIndex(h, s)
		}
		concat(h, raw)
	case "Text":
		var vs []Text
		for _, s := range raw {
			vs = append(vs, Text(s))
			lenIndex(h, Text(s))
		}
		concat(h, vs)
		conv[Text, Raw](h, vs)
	case "Raw":
		for _, s := range raw {
			lenIndex(h, Raw(s))
		}
	case "bytes":
		for _, s := range raw {
			lenIndex(h, []byte(s))
		}
	case "Name":
		var vs []Name
		for _, s := range raw {
			vs = append(vs, Name(s))
		}
		concat(h, vs)
		conv[Name, []byte](h, vs)
	case "conv":
		conv[string, []byte](h, raw)
		conv[string, Raw](h, raw)
	case "runes":
		runes[int8, string](h)
		runes[int32, Text](h)
		runes[uint8, Name](h)
		runes[uint32, string](h)
		runes[int, Text](h)
		runes[uint64, string](h)
	}
	h.done()
}

func main() {
	for _, n := range []string{"string", "Text", "Raw", "bytes", "Name", "conv", "runes"} {
		sweep(n)
	}
}
`)
}

func complexProgram(b *strings.Builder, rng *rand.Rand) {
	vals := []string{"0", "1", "-1", "1i", "-1i", "1+1i", "2-3i", "0.5+0.25i", "1e10+1e-10i", "1e300+1e300i", "-1e-300-1e-300i", "3+4i", "complex(math.Inf(1), 0)", "complex(math.Inf(1), 1)", "complex(1, math.Inf(-1))", "complex(math.NaN(), 0)", "complex(0, math.NaN())", "complex(math.Copysign(0, -1), 0)"}
	for range 10 {
		vals = append(vals, fmt.Sprintf("complex(%v, %v)", rng.Float64()*20-10, rng.Float64()*20-10))
	}
	fmt.Fprintf(b, "\nvar raw = []complex128{%s}\n", strings.Join(vals, ", "))
	b.WriteString(`
type Complex interface{ ~complex64 | ~complex128 }

type MyC64 complex64
type MyC128 complex128

func c128[C Complex](h *hasher, c C) {
	h.f64(real(complex128(c)))
	h.f64(imag(complex128(c)))
}

func sweep[C Complex](name string) {
	h := newHasher(name)
	vs := make([]C, len(raw))
	for i, r := range raw {
		vs[i] = C(r)
	}
	for _, a := range vs {
		c128(h, -a)
		c128(h, +a)
		c128(h, a*a)
		c128(h, a+1)
		c128(h, a-1i)
		c128(h, a*2)
		c128(h, 1/a)
		x := a
		x += a
		x *= a
		x /= 3
		x -= 1
		c128(h, x)
		h.f64(real(complex128(a)))
		h.f64(imag(complex128(a)))
		h.str(fmt.Sprint(a))
		h.str(fmt.Sprintf("%v %.2f %g", a, a, a))
		for _, c := range vs {
			c128(h, a+c)
			c128(h, a-c)
			c128(h, a*c)
			c128(h, a/c)
			h.bool(a == c)
			h.bool(a != c)
		}
	}
	h.done()
}

func main() {
	sweep[complex64]("complex64")
	sweep[complex128]("complex128")
	sweep[MyC64]("MyC64")
	sweep[MyC128]("MyC128")
}
`)
}

func orderProgram(b *strings.Builder, rng *rand.Rand) {
	b.WriteString(strings.Replace(intDefs, "type MyI64 int64", "type MyI64 int64\ntype MyF float64\ntype MyS string", 1))
	fmt.Fprintf(b, "\nvar seed uint64 = %d\n", rng.Int63())
	b.WriteString(`
func next() uint64 {
	seed += 0x9E3779B97F4A7C15
	z := seed
	z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9
	z = (z ^ (z >> 27)) * 0x94D049BB133111EB
	return z ^ (z >> 31)
}

type Ordered interface {
	~int8 | ~int16 | ~int32 | ~int64 | ~int | ~uint8 | ~uint16 | ~uint32 | ~uint64 | ~uint | ~uintptr | ~float32 | ~float64 | ~string
}

type Num interface {
	~int8 | ~int16 | ~int32 | ~int64 | ~int | ~uint8 | ~uint16 | ~uint32 | ~uint64 | ~uint | ~uintptr | ~float32 | ~float64
}

func genNum[T Num]() T {
	v := next()
	switch v % 7 {
	case 0:
		return 0
	case 1:
		return T(v % 5)
	case 2:
		return T(v%100) + 100
	default:
		k := uint64(1 << 20)
		return T(v>>40) - T(k)
	}
}

func genStr[T ~string]() T { return T(fmt.Sprint(next() % 40)) }

func less[T Ordered](a, b T) bool { return a < b }

func isort[T Ordered](s []T) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && less(s[j], s[j-1]); j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

func hashOf[T Ordered](h *hasher, v T) {
	switch x := any(v).(type) {
	case float32:
		h.f32(x)
	case float64:
		h.f64(x)
	case MyF:
		h.f64(float64(x))
	case string:
		h.str(x)
	case MyS:
		h.str(string(x))
	default:
		h.str(fmt.Sprint(v))
	}
}

func sweep[T Ordered](name string, gen func() T) {
	h := newHasher(name)
	for round := 0; round < 12; round++ {
		xs := make([]T, 1+round*5)
		for i := range xs {
			xs[i] = gen()
		}
		for _, a := range xs {
			for _, b := range xs {
				hashOf(h, max(a, b))
				hashOf(h, min(a, b))
				h.bool(a < b)
				h.bool(a >= b)
				h.u64(uint64(cmp.Compare(a, b) + 1))
				h.bool(cmp.Less(a, b))
			}
		}
		ys := slices.Clone(xs)
		isort(ys)
		zs := slices.Clone(xs)
		slices.Sort(zs)
		h.bool(slices.Equal(ys, zs))
		ws := slices.Clone(xs)
		slices.SortFunc(ws, func(a, b T) int { return cmp.Compare(b, a) })
		slices.Reverse(ws)
		h.bool(slices.Equal(ws, zs))
		for _, y := range ys {
			hashOf(h, y)
		}
		hashOf(h, slices.Max(xs))
		hashOf(h, slices.Min(xs))
		h.bool(slices.IsSorted(zs))
		h.bool(slices.IsSorted(xs))
		for _, x := range xs {
			i, found := slices.BinarySearch(zs, x)
			h.u64(uint64(i))
			h.bool(found)
			h.u64(uint64(slices.Index(xs, x)))
			h.bool(slices.Contains(zs, x))
		}
		zs = slices.Compact(zs)
		h.u64(uint64(len(zs)))
		h.u64(uint64(slices.Compare(xs, ys) + 1))
	}
	h.done()
}

func main() {
	sweep("int8", genNum[int8])
	sweep("uint8", genNum[uint8])
	sweep("int16", genNum[int16])
	sweep("uint16", genNum[uint16])
	sweep("int32", genNum[int32])
	sweep("uint32", genNum[uint32])
	sweep("int64", genNum[int64])
	sweep("uint64", genNum[uint64])
	sweep("int", genNum[int])
	sweep("uint", genNum[uint])
	sweep("uintptr", genNum[uintptr])
	sweep("float32", genNum[float32])
	sweep("float64", genNum[float64])
	sweep("MyI8", genNum[MyI8])
	sweep("MyU16", genNum[MyU16])
	sweep("MyF", genNum[MyF])
	sweep("string", genStr[string])
	sweep("MyS", genStr[MyS])
}
`)
}
